"E (MeV)":"E (МэВ)",
"E = (3/2)kT, k = 1,38·10⁻²³ J/K — Bolsman doimiysi. O'rtacha kinetik energiya faqat mutlaq haroratga bog'liq.":"E = (3/2)kT, k = 1,38·10⁻²³ J/K — постоянная Больцмана. Средняя кинетическая энергия зависит только от абсолютной температуры.",
"E = hν = hc/λ, h = 6,63·10⁻³⁴ J·s. Chastota qancha katta (to'lqin uzunligi qancha kichik) bo'lsa, foton energiyasi shuncha katta.":"E = hν = hc/λ, h = 6,63·10⁻³⁴ J·s. Чем больше частота (чем меньше длина волны), тем больше энергия фотона.",
