"EYK nimaga proporsional? Magnit to'xtaganda EYK qancha?":"Чему пропорциональна ЭДС? Чему равна ЭДС, когда магнит остановился?",
"EYuK 12 V, ichki qarshiligi 1 Ω bo'lgan manbaga 5 Ω tashqi qarshilik ulandi. Zanjirdagi tok kuchini toping.":"К источнику с ЭДС 12 V и внутренним сопротивлением 1 Ω подключено внешнее сопротивление 5 Ω. Найдите силу тока в цепи.",
"E_k = hν − A — faqat chastota va chiqish ishiga bog'liq. Intensivlik faqat chiqqan elektronlar sonini (to'yinish tokini) oshiradi.":"E_k = hν − A — зависит только от частоты и работы выхода. Интенсивность увеличивает лишь число вылетевших электронов (ток насыщения).",
"E_k = hν − A — qiyaligi h bo'lgan to'g'ri chiziq; u barcha metallar uchun bir xil. Grafikning ν o'qi bilan kesishish nuqtasi — qizil chegara ν_min.":"E_k = hν − A — прямая с наклоном h; он одинаков для всех металлов. Точка пересечения графика с осью ν — красная граница ν_min.",
