"Impulsning saqlanish qonuni — interaktiv simulyatsiya: ishqalanishsiz yo'ldagi ikki aravacha, metrli shkala, tezlik va impuls vektorlari, to'qnashuvdan oldin va keyingi impuls hamda kinetik energiya ustunlari":"Закон сохранения импульса — интерактивная симуляция: две тележки на дорожке без трения, метровая шкала, векторы скорости и импульса, столбики импульса и кинетической энергии до и после столкновения",
"Impulsning saqlanish qonuni. Elastik va noelastik to'qnashuvlar":"Закон сохранения импульса. Упругие и неупругие столкновения",
"Impulsning saqlanish qonuni:":"Закон сохранения импульса:",
"Impulsning saqlanishi: m₁v₁ = (m₁ + m₂)·u → u = 2·3/(2 + 1) = 2 m/s":"Сохранение импульса: m₁v₁ = (m₁ + m₂)·u → u = 2·3/(2 + 1) = 2 m/s",
"Induksion tok doimo soat mili yo'nalishida oqadi":"Индукционный ток всегда течёт по часовой стрелке",
"Induksion tok faqat magnit oqimi o'zgarganda hosil bo'ladi. Magnit yoki g'altak harakatlanmasa, oqim o'zgarmaydi va tok yo'q.":"Индукционный ток возникает только при изменении магнитного потока. Если ни магнит, ни катушка не движутся, поток не изменяется и тока нет.",
"Induksion tok faqat o'zgarmas magnit maydonda hosil bo'ladi":"Индукционный ток возникает только в постоянном магнитном поле",
"Induksion tok magnit oqimining kattaligiga proporsional":"Индукционный ток пропорционален величине магнитного потока",
"Induksion tok o'zini vujudga keltirgan magnit oqimi o'zgarishiga qarshilik qiladi":"Индукционный ток противодействует изменению магнитного потока, которое его вызвало",
"Induksion tokning magnit maydoni tashqi oqim o'zgarishini kompensatsiyalashga intiladi. Bu energiyaning saqlanish qonunining natijasi.":"Магнитное поле индукционного тока стремится компенсировать изменение внешнего потока. Это следствие закона сохранения энергии.",
