"Magnit tezligi":"Скорость магнита",
"Magnit tezroq harakatlansa — EYK katta. Magnit to'xtasa — EYK nolga teng (oqim bor, lekin o'zgarmayapti!). O'ramlar soni N oshsa — EYK proporsional oshadi. Galvanometr strelkasi magnit yaqinlashganda bir tomonga, uzoqlashganda ikkinchi tomonga og'adi — bu Lens qoidasi.":"Чем быстрее движется магнит — тем больше ЭДС. Магнит остановился — ЭДС равна нулю (поток есть, но не меняется!). При увеличении числа витков N ЭДС растёт пропорционально. Стрелка гальванометра при приближении магнита отклоняется в одну сторону, при удалении — в другую: это правило Ленца.",
