"Quyoshning tortishish kuchi masofa kvadratiga teskari proporsional (1/r²); bunday kuch ta'sirida yopiq orbita ellips bo'ladi (Nyuton isbotlagan).":"Сила притяжения Солнца обратно пропорциональна квадрату расстояния (1/r²); под действием такой силы замкнутая орбита является эллипсом (доказал Ньютон).",
"R = 0 da I_q.t. = ℰ/r: tok faqat manbaning ichki qarshiligi bilan cheklanadi. Ichki qarshiligi kichik akkumulyatorlarda bu tok xavfli darajada katta.":"При R = 0 I_q.t. = ℰ/r: ток ограничен только внутренним сопротивлением источника. У аккумуляторов с малым внутренним сопротивлением этот ток опасно велик.",
"R = U/I → 1 Om = 1 V/1 A. Amper — tok kuchi, volt — kuchlanish, vatt — quvvat birligi.":"R = U/I → 1 Ом = 1 V/1 A. Ампер — единица силы тока, вольт — напряжения, ватт — мощности.",
"R = ρl/S: qarshilik uzunlikka to'g'ri, ko'ndalang kesim yuziga teskari proporsional.":"R = ρl/S: сопротивление прямо пропорционально длине и обратно пропорционально площади поперечного сечения.",
"R_par = 4·12/(4 + 12) = 48/16 = 3 Ω; R_um = 3 + 7 = 10 Ω":"R_par = 4·12/(4 + 12) = 48/16 = 3 Ω; R_общ = 3 + 7 = 10 Ω",
