"Sig'imi 10 mkF bo'lgan kondensator 200 V kuchlanishgacha zaryadlandi. Kondensator zaryadini toping (millikulonda).":"Конденсатор ёмкостью 10 мкF зарядили до напряжения 200 V. Найдите заряд конденсатора (в милликулонах).",
