"Sochuvchi linza haqiqiy buyumning har doim qanday tasvirini beradi?":"Какое изображение действительного предмета всегда даёт рассеивающая линза?",
"Sochuvchi linzadan o'tgan nurlar tarqaladi; ularning davomlari kesishib, buyum tomonida mavhum, to'g'ri, kichraygan tasvir hosil qiladi.":"Лучи, прошедшие через рассеивающую линзу, расходятся; их продолжения пересекаются и образуют со стороны предмета мнимое, прямое, уменьшенное изображение.",
