"Sonlar o'rniga":"Вместо чисел",
"Sozlama o'zgartirilsa, joriy otish bekor qilinadi va jism to'pga qaytadi. Oldingi traektoriyalar (5 tagacha) solishtirish uchun xira ko'rinishda saqlanadi.":"При изменении настройки текущий бросок отменяется и тело возвращается в пушку. Предыдущие траектории (до 5) сохраняются бледными для сравнения.",
