"Stoletov qonunlari:":"Законы Столетова:",
"Surxondaryo viloyati":"Сурхандарьинская область",
"Suv":"Вода",
"Suv → havo: α_kr ≈ 48.8°; olmos → havo: ≈ 24.4°":"Вода → воздух: α_кр ≈ 48.8°; алмаз → воздух: ≈ 24.4°",
"Suvdan havoga chiqayotgan nurlar normaldan uzoqlashadi; ko'z ularning davomini kesishgan joyda — yuqoriroqda ko'radi (tik qaraganda h' ≈ h/n ≈ 0,75h).":"Лучи, выходящие из воды в воздух, отклоняются от нормали; глаз видит изображение в точке пересечения их продолжений — выше (при взгляде отвесно h' ≈ h/n ≈ 0,75h).",
"Suvning sindirish ko'rsatkichi 1,33. Yorug'likning suvdagi tezligi taxminan qancha (c = 3·10⁸ m/s)?":"Показатель преломления воды 1,33. Какова примерно скорость света в воде (c = 3·10⁸ m/s)?",
"T = 2π√(l/g) = 6,283·√(1/1,62) = 6,283·0,7857 ≈ 4,94 s (Yerda bu mayatnik davri ≈ 2 s)":"T = 2π√(l/g) = 6,283·√(1/1,62) = 6,283·0,7857 ≈ 4,94 s (на Земле период этого маятника ≈ 2 s)",
"T = 2π√(l/g) formulasida massa yo'q: og'irlik kuchi ham, jismning inertligi ham massaga proporsional bo'lgani uchun ular qisqaradi.":"В формуле T = 2π√(l/g) массы нет: и сила тяжести, и инертность тела пропорциональны массе, поэтому они сокращаются.",
"T = 2π√(m/k) formulasida g yo'q: davr faqat massa va bikrlikka bog'liq, shuning uchun Oyda ham o'zgarmaydi (faqat muvozanat holati siljiydi).":"В формуле T = 2π√(m/k) нет g: период зависит только от массы и жёсткости, поэтому на Луне он не изменится (сместится лишь положение равновесия).",
"T = 2π√(m/k), bu yerda m — yuk massasi, k — prujina bikrligi. Yuk og'ir bo'lsa sekinroq, prujina bikr bo'lsa tezroq tebranadi.":"T = 2π√(m/k), где m — масса груза, k — жёсткость пружины. Чем тяжелее груз, тем медленнее, а чем жёстче пружина, тем быстрее колебания.",
"T = 2π√(m/k): massa va bikrlikni o'zgartirib davrni o'lchang. Kinetik va potensial energiya almashinuvi, so'nuvchi tebranish va x(t) grafigi.":"T = 2π√(m/k): изменяйте массу и жёсткость и измеряйте период. Взаимопревращение кинетической и потенциальной энергии, затухающие колебания и график x(t).",
"T nazariy":"T теор.",
"T nazariy (s)":"T теор. (s)",
"T nazariy (s)²":"T теор. (s)²",
"T o'lch":"T изм.",
"T o'lch. (s)":"T изм. (s)",
"T ~ 1/√g. g 6 marta kamaysa, davr √6 ≈ 2,45 marta ortadi — Oyda mayatnik sekinroq tebranadi.":"T ~ 1/√g. Если g уменьшится в 6 раз, период увеличится в √6 ≈ 2,45 раза — на Луне маятник колеблется медленнее.",
"T ~ √l, shuning uchun uzunlik 4 marta ortsa, davr √4 = 2 marta ortadi.":"T ~ √l, поэтому при увеличении длины в 4 раза период увеличивается в √4 = 2 раза.",
"T ~ √m: √4 = 2, demak davr 2 marta ortadi.":"T ~ √m: √4 = 2, значит период увеличится в 2 раза.",
"Ta'lim maqsadida bepul foydalanish uchun":"Бесплатно для использования в образовательных целях",
"Tabiiy radioaktiv manbalar alfa zarralarni taxminan 5–7 MeV energiya bilan chiqaradi.":"Естественные радиоактивные источники испускают альфа-частицы с энергией примерно 5–7 MeV.",
"Tajriba Tomsonning \"qaymoqli tort\" (mayizli pudding) modelini rad etib, Rezerfordning yadroli (planetar) modeliga olib keldi.":"Опыт опроверг модель Томсона («пудинг с изюмом») и привёл к ядерной (планетарной) модели Резерфорда.",
"Tajriba natijasi qanday atom modeliga olib keldi?":"К какой модели атома привёл результат опыта?",
"Tajriba natijasi: ... Grafikdan ... chiqdi. Nazariy qiymat bilan farq ...":"Результат опыта: ... По графику получилось ... Отличие от теоретического значения ...",
