"U ni 2 baravar oshiring — I ham 2 baravar oshadi. R ni 2 baravar oshiring — I 2 baravar kamayadi. Zarrachalar tezligi tok kuchiga proporsional, rezistorning qizishi esa quvvatga (P = U·I) bog'liq.":"Увеличьте U в 2 раза — I тоже возрастёт в 2 раза. Увеличьте R в 2 раза — I уменьшится в 2 раза. Скорость частиц пропорциональна силе тока, а нагрев резистора зависит от мощности (P = U·I).",
"U ni 6 V ga qaytarib, R ni 2 barobar oshiring (20 Ω) — I qanday o'zgardi?":"Верните U = 6 V и увеличьте R в 2 раза (20 Ω) — как изменилась I?",
"U ni o'zgartiring yoki «I–U»":"Меняйте U или нажмите",
"U_t = mv²_max/2":"U_t = mv²_max/2",
"Uchala qonun alohida bo'limda: ellips orbita, teng yuzalar va T²=a³ munosabati. Sekkizta sayyora haqiqiy ma'lumotlar bilan.":"Все три закона в отдельных разделах: эллиптическая орбита, равные площади и соотношение T²=a³. Восемь планет с реальными данными.",
"Uchinchi qonun formulasi qanday?":"Какова формула третьего закона?",
"Uchinchi qonunni kim nazariy asoslab berdi?":"Кто теоретически обосновал третий закон?",
"Uchish uzoqligi (L):":"Дальность полёта (L):",
"Uchish uzoqligi, ko'tarilish balandligi va parvoz vaqti burchakka qanday bog'liq?":"Как дальность полёта, высота подъёма и время полёта зависят от угла?",
"Uchta yarim yemirilish davri o'tgach, dastlabki radioaktiv yadrolarning qancha qismi yemirilmay qoladi?":"Какая доля исходных радиоактивных ядер останется нераспавшейся по прошествии трёх периодов полураспада?",
"Uglerod-14":"Углерод-14",
"Uglerod-14 ning yarim yemirilish davri 5730 yil. Qadimiy yog'och namunasida C-14 miqdori tirik daraxtdagiga nisbatan 8 marta kam. Namunaning yoshini toping.":"Период полураспада углерода-14 — 5730 лет. Содержание C-14 в образце древней древесины в 8 раз меньше, чем в живом дереве. Найдите возраст образца.",
"Uglerod-14: T½ = 5730 yil, β⁻-yemirilish → ¹⁴N. Vaqt masshtablangan:":"Углерод-14: T½ = 5730 лет, β⁻-распад → ¹⁴N. Время масштабировано:",
"Ularning impulslari moduli teng, zambarak massasi esa ancha katta":"Модули их импульсов равны, а масса пушки намного больше",
"Ularning o'tuvchanligi bir xil":"Их проникающая способность одинакова",
"Umumiy":"Всего",
