"Uzilgan, d: 2 → 4 mm: q o'zgarmas, U = 40 V (2 marta), E o'zgarmas, W 2 marta ortadi — plastinkalarni ajratishda bajarilgan ish hisobiga":"Отключён, d: 2 → 4 mm: q не меняется, U = 40 V (в 2 раза больше), E не меняется, W возрастает в 2 раза — за счёт работы, совершённой при раздвигании пластин",
"Uzluksiz":"Непрерывно",
"Uzunligi 0,5 m bo'lgan o'tkazgich induksiyasi 0,4 T bo'lgan magnit maydonda induksiya chiziqlariga perpendikulyar 10 m/s tezlik bilan harakatlanmoqda. O'tkazgich uchlaridagi induksiya EYuK ni toping.":"Проводник длиной 0,5 m движется в магнитном поле с индукцией 0,4 T перпендикулярно линиям индукции со скоростью 10 m/s. Найдите ЭДС индукции на концах проводника.",
"Uzunligi 2,5 m bo'lgan matematik mayatnikning tebranish davrini toping (g = 9,81 m/s²).":"Найдите период колебаний математического маятника длиной 2,5 m (g = 9,81 m/s²).",
"Uzunligi 5 m, balandligi 1,5 m bo'lgan qiya tekislik bo'ylab 60 kg yukni tekis tortib chiqarishda 250 N kuch qo'yildi. FIK ni toping (g = 9,8 m/s²).":"При равномерном подъёме груза массой 60 kg по наклонной плоскости длиной 5 m и высотой 1,5 m была приложена сила 250 N. Найдите КПД (g = 9,8 m/s²).",
"Uzunligi l bo'lgan o'tkazgich magnit maydonda induksiya chiziqlariga perpendikulyar v tezlik bilan harakatlanmoqda. Unda hosil bo'ladigan induksiya EYuK qaysi?":"Проводник длиной l движется в магнитном поле со скоростью v перпендикулярно линиям индукции. Какая ЭДС индукции в нём возникает?",
"Uzunlikni o'zgartirib (0.5 m, 1.5 m, 2 m) tajribani takrorlang":"Повторите опыт при другой длине (0.5 m, 1.5 m, 2 m)",
