"modelda nurlarning yorqinligi qaytgan (R) va o'tgan (T = 1 − R) energiya ulushiga mos (Frenel formulalari, qutblanmagan yorug'lik). Havo → shisha tik tushishda faqat ~4% qaytadi, α 90° ga yaqinlashganda esa qaytgan ulush keskin ortadi. α":"в модели яркость лучей соответствует доле отражённой (R) и прошедшей (T = 1 − R) энергии (формулы Френеля, неполяризованный свет). При нормальном падении воздух → стекло отражается лишь ~4%, а при приближении α к 90° доля отражённого резко растёт. При приближении к α",
"modelda qiymatlar":"в модели величины даны",
"modelda to'qnashuvdan keyingi tezliklar formuladan ko'chirilmaydi — aravaning to'qnashuv paytidagi va hozirgi koordinatalari bo'yicha v′ = Δx/Δt sifatida o'lchanadi. To'qnashuv paytining o'zi ham kadrlar orasida analitik aniqlanadi, shuning uchun aravalar bir-biridan «o'tib ketmaydi». Biror arava yo'l chetidagi to'xtatgichga yetganda tajriba tugaydi.":"в модели скорости после столкновения не берутся из формулы — они измеряются как v′ = Δx/Δt по координатам тележки в момент столкновения и в текущий момент. Сам момент столкновения тоже определяется аналитически между кадрами, поэтому тележки не «проходят» друг сквозь друга. Опыт заканчивается, когда одна из тележек достигает упора на краю дорожки.",
"muhim:":"важен:",
