"qonun alohida yadro uchun emas, juda ko'p yadrolar uchun o'rinli. Yadrolar soni N bo'lganda tasodifiy chetlanish taxminan √N ga teng, nisbiy chetlanish esa 1/√N: N₀ = 400 da t = T½ da N ≈ 200 ± 10 (±5%), N₀ = 100 da N ≈ 50 ± 5 (±10%). Haqiqiy namunada yadrolar soni ~10²⁰ bo'lgani uchun egri chiziq deyarli mukammal silliq bo'ladi.":"закон справедлив не для отдельного ядра, а для очень большого числа ядер. При числе ядер N случайное отклонение примерно равно √N, а относительное — 1/√N: при N₀ = 400 и t = T½ N ≈ 200 ± 10 (±5%), при N₀ = 100 N ≈ 50 ± 5 (±10%). В реальном образце ~10²⁰ ядер, поэтому кривая получается практически идеально гладкой.",
"qonuni bo'yicha kamayadi, davr esa biroz ortadi: T = 2π / √(k/m − b²/4m²). Masalan, m = 0.5 kg, k = 20 N/m, b = 0.2 kg/s da farq atigi ~0.05%, lekin yengil yuk va katta b da (m = 0.1 kg, k = 5 N/m, b = 0.5 kg/s) u ~7% ga yetadi.":", а период немного растёт: T = 2π / √(k/m − b²/4m²). Например, при m = 0.5 kg, k = 20 N/m, b = 0.2 kg/s разница лишь ~0.05%, но для лёгкого груза и большого b (m = 0.1 kg, k = 5 N/m, b = 0.5 kg/s) она достигает ~7%.",
