"— molekulalari o'lchami idish hajmiga nisbatan juda kichik va o'zaro faqat to'qnashganda ta'sirlashadigan gaz modeli. Uning holati bosim (p), hajm (V) va absolyut harorat (T) bilan aniqlanadi hamda":"— модель газа, размеры молекул которого очень малы по сравнению с объёмом сосуда, а взаимодействуют они только при столкновениях. Его состояние определяется давлением (p), объёмом (V) и абсолютной температурой (T) и подчиняется",
