"• Impuls momenti saqlanish qonunidan kelib chiqadi":"• Следует из закона сохранения момента импульса",
"• L = mvr = const (impuls momenti)":"• L = mvr = const (момент импульса)",
"• Perigeliy (eng yaqin): a(1-e)":"• Перигелий (ближайшая точка): a(1-e)",
"• Sayyora Quyoshdan uzoqroq bo'lganda sekinroq harakat qiladi":"• Дальше от Солнца планета движется медленнее",
"• Sayyora Quyoshga yaqinroq bo'lganda tezroq harakat qiladi":"• Ближе к Солнцу планета движется быстрее",
"• T - orbital davr (yil)":"• T — период обращения (лет)",
"• Tezlik (vis-viva): v = √(GM(2/r − 1/a)) — perigeliyda maksimal, afeliyda minimal":"• Скорость (vis-viva): v = √(GM(2/r − 1/a)) — максимальна в перигелии, минимальна в афелии",
"• Yer uchun: T = 1 yil, a = 1 AU → T²/a³ = 1":"• Для Земли: T = 1 год, a = 1 а. е. → T²/a³ = 1",
